// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the array length (we use a uint8 to keep gas reasonable) and a selector parameter value
    function testFuzz_property(uint8 n, uint256 v) public {
        // keep array length in a reasonable range but allow zero to be excluded by contract
        uint256 len = uint256(n);
        vm.assume(len > 0); // transfer requires _tos.length > 0

        // deploy a callee that will revert when its transferFrom is called
        ReverterCallee bad = new ReverterCallee();

        // construct tos array with `len` entries all equal to the bad callee address
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(bad);

        bool ok;
        // call and observe whether transfer reverts or not
        try c.transfer(address(0x1234), address(bad), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): The reference implementation always reverts (ok == false)
        // when the callee reverts; the mutant that removed the require may return true (ok == true) for some inputs.
        assertTrue(ok == false);
    }
}

// Adversarial callee: has the exact signature transferFrom(address,address,uint256)
// and always reverts to simulate a failing external call. This exercises the branch
// where the reference contract requires the external call to succeed.
contract ReverterCallee {
    function transferFrom(address, address, uint256) external pure {
        revert("revert from callee");
    }
}
